def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([]), fmt([9]), fmt([4, 4, 4]), fmt([1, 5, 2, 3]), fmt([2, 1]), fmt([3, 2, 1]),
             fmt([1, 2, 3, 4, 5, 6]), fmt([10**9, -10**9, 10**9, -10**9])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12, 14):
        for _ in range(2):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(12)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(1000)]))
    tests.append(fmt([7] * 1000))
    tests.append(fmt([rng.randint(0, 5) for _ in range(1000)]))
    tests.append(fmt([i * i for i in range(1000)]))
    return tests

